style.css:
@-moz-document url-prefix("https://open.spotify.com") {
/* General background pink */
  html, body {
    background-color: #ff69b4 !important;
    color: #ffffff !important;
  }

  /* Sidebar pink and text white */
  .Root__nav-bar,
  .main-yourLibraryX-library,
  .main-collectionLinkButton-collectionLinkButton {
    background-color: #ff69b4 !important;
    color: #ffffff !important;
    border: none !important;
  }

  .Root__nav-bar a,
  .main-yourLibraryX-library a {
    color: #ffffff !important;
  }

  /* Remove black borders and shadows everywhere */
  * {
    border-color: #ff69b4 !important;
    box-shadow: none !important;
  }

  /* Leopard print background in the playlist header */
  .main-entityHeader-background {
    background-image: url("https://i.imgur.com/Zn4CB0U.jpg"); /* Replace with your leopard print */
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-color: #ff69b4 !important;
  }

  /* Remove overlays over the header image */
  .main-entityHeader-overlay,
  .main-entityHeader-shadow {
    background: none !important;
  }

  /* Playlist header text styling */
  .main-entityHeader-title,
  .main-entityHeader-subtitle {
    color: #ffffff !important;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
    text-shadow: 2px 2px #ff1493 !important;
  }

  /* Tracklist table background pink */
  .main-trackList-trackList,
  .main-trackList-trackListRow {
    background-color: rgba(255, 105, 180, 0.2) !important;
    border: none !important;
  }

  /* Tracklist rows hover effect pinker */
  .main-trackList-trackListRow:hover {
    background-color: rgba(255, 20, 147, 0.3) !important;
  }

  /* Tracklist text white */
  .main-trackList-trackListRow span,
  .main-trackList-trackListRow div,
  .main-trackList-trackListRow a {
    color: #ffffff !important;
  }

  /* Buttons pink */
  button,
  .Button-sc-1dqy6lx-0,
  .main-playButton-PlayButton,
  .main-playButton-PlayButton button {
    background-color: #ff1493 !important;
    color: #ffffff !important;
    border-radius: 8px !important;
    border: none !important;
  }

  /* Remove any dark overlay at the scroll area bottom */
  .main-view-container__scroll-node::after {
    background: none !important;
  }

  /* Remove thin black dividers in side menus */
  .main-rootlist-rootlistDivider {
    background: none !important;
  }

  /* Hello Kitty watermark overlay */
  .Root__main-view::after {
    content: "";
    background: url("https://i.imgur.com/fzHyQ9n.png") no-repeat center center; /* Replace with your Hello Kitty */
    background-size: 150px;
    opacity: 0.1;
    position: fixed;
    top: 50%;
    left: 50%;
    width: 150px;
    height: 150px;
    transform: translate(-50%, -50%);
    pointer-events: none;
    z-index: 9999;
  }
}
